            if is_valid_recolor(current_picture, r, c):
                recolor(current_picture, r, c)
                operations.append(f"1 {r + 1} {c + 1}")

    print(initial_picture_index)
    print(len(operations))
    for operation in operations:
        print(operation)

if __name__ == "__main__":
    main()
